          "name": "圣安东尼向鱼传道动机 (Fischpredigt Moto Perpetuo)",
          "name_en": "St. Anthony's Sermon to the Fishes (Perpetual 3/8)",
          "color": "#8b5cf6",
          "earprint": "源自《少年魔角》歌曲，单簧管与弦乐永不停歇的盘旋音流，讽刺世人听完神圣布道后依然浑噩如故的荒诞日常。",
          "earprint_en": "Derived from the Wunderhorn song, a ceaseless 3/8 whirlpool satirizing the meaningless bustle of existence where everyone forgets the sermon immediately.",
          "firstCarrier": "C4 - D4 - Eb4 - F4 - G4 - Eb4 - C4 (sinuous 16th-note swirl)",
