          "kind": "normal",
          "title": "原光起句（一）：“O Röschen rot!”——女低音独唱无伴奏进入与降D大调铜管圣咏光环",
          "title_en": "Urlicht Opening I: \"O Röschen rot!\" — Contralto Solo Entry and D-flat Major Brass Halo",
          "desc": "从第三乐章的C小调废墟直接跨入降D大调（拿波里关系调）的神圣净土！考热娜（Magdalena Kožená）温暖而纯净的嗓音仿佛来自天国的第一缕晨曦。",
          "desc_en": "Stepping directly from the C minor wreckage of Movement III into the sacred sanctuary of D-flat major! Magdalena Kožená's warm, unadorned voice shines like the first ray of heavenly dawn.",
          "foreground": "女低音独唱：在毫无伴奏的寂静中，以质朴虔诚的赤子之音唱出“啊，红玫瑰！（O Röschen rot!）”",
          "foreground_en": "Contralto Solo: Steps out of silence to sing 'O Röschen rot!' with unadorned, childlike devotion",
