          "desc_en": "Movement V explodes with overwhelming theatrical shock! Though the soul glimpsed faith in Urlicht, it is plunged immediately into the apocalyptic storm of the Last Judgment.",
          "foreground": "全弦乐、木管与铜管：以狂野的速度（Wild herausfahrend）瞬间撕碎《原光》的宁静，重现第三乐章高潮的ffff绝望尖叫和弦",
