          "earprint": "C小调严峻的附点葬礼步伐，配以低音提琴沉重的四分音符踏步，象征泰坦英雄遗体入土时的悲剧重负。",
          "earprint_en": "Stern C minor dotted march rhythm over trudging bass ostinato, embodying the tragic weight of the fallen hero's funeral procession.",
