          "name_en": "The Scream of Despair (Aufschrei / Totengreif Chord)",
          "color": "#e11d48",
          "earprint": "对虚无世界发出的撕心裂肺的尖叫（ffff），在第三乐章高潮炸裂，又在第五乐章开篇原样重现。",
          "earprint_en": "Shattering ffff dissonance of existential nausea and terror that erupts at the climax of the Scherzo and rips open the Finale.",
