          "name": "原光圣咏与赤子信仰主题 (Urlicht Chorale & Faith)",
          "name_en": "Urlicht (Primal Light) Brass Chorale & Contralto Lied",
          "color": "#f59e0b",
          "earprint": "女低音以毫无修饰的赤子之声唱出“啊，红玫瑰！”，铜管圣咏如教堂彩窗般庄严笼罩，点燃通向上帝之光。",
          "earprint_en": "Unadorned contralto invocation ('O Röschen rot!') framed by a hushed D-flat major brass chorale, illuminating the soul's return to God.",
          "firstCarrier": "Ab4 - Bb4 - Db5 - Ab4 - F4 (O Röschen rot!)",
