          "color": "#3b82f6",
          "earprint": "大地寂灭之后，四支后台小号与圆号从四面八方吹响孤寂的集结号，舞台上仅剩长笛与短笛模仿坟墓上最后一只夜莺的啼鸣。",
          "earprint_en": "Across a devastated landscape, four offstage trumpets and horns sound the Great Summons while onstage flute and piccolo intone a lone nightingale over the graves.",
