      "title_en": "The Apocalyptic Sequence: Four Avatars of 'Dies Irae'",
      "summary": "中世纪天主教圣咏《震怒之日》在第一乐章作为展开部暗号吹响，在第五乐章化为长号的审判号角与死者进行曲的核心旋律。",
