      "title_en": "Spatial Dimension: Offstage Brass & Percussion Calls",
      "summary": "马勒利用柏林爱乐大厅的空间纵深，在第五乐章部署后台小号、圆号与定音鼓，创造出天籁、末日号角与大审判的神秘远近对比。",
