  "glossary": [
    {
      "term": "Totenfeier (葬礼)",
      "term_en": "Totenfeier (Funeral Rites)",
      "definition": "第一乐章的原名，源自波兰诗人亚当·密茨凯维奇的史诗《先人祭》。马勒在此为第一交响曲中的英雄巨擘举行安魂葬礼。",
      "definition_en": "Original title of Movement I, inspired by Adam Mickiewicz's epic drama; Mahler buries the heroic titan of his First Symphony."
    },
    {
      "term": "Urlicht (原光)",
      "term_en": "Urlicht (Primal Light)",
      "definition": "第四乐章标题，源自德意志民歌集《少年魔角》。代表灵魂深处对纯真天国源头之光的绝对笃信。",
      "definition_en": "Title of Movement IV from Des Knaben Wunderhorn, expressing childlike, unshakeable faith in the primal divine source of light."
    },
    {
      "term": "Fernorchester (后台乐队)",
      "term_en": "Fernorchester (Offstage Band)",
      "definition": "放置在观众席外或舞台后方的声乐与管乐群（4支小号、4支圆号、定音鼓与钹），用以创造超越尘世的三维空间音效。",
      "definition_en": "Ensemble of trumpets, horns, and percussion placed outside the hall to create supernatural spatial depth and otherworldly acoustic distance."
    },
    {
      "term": "Der Grosse Appell (大点名)",
      "term_en": "Der Grosse Appell (The Great Summons)",
      "definition": "终曲中四支后台小号与圆号在不同方向相继吹响的四音号角声，宣告全宇宙所有的死者接受唤醒。",
      "definition_en": "The apocalyptic spatial trumpet and horn fanfare in the Finale sounding the awakening of all departed souls."
    },
    {
      "term": "Dies Irae (震怒之日)",
      "term_en": "Dies Irae (Day of Wrath)",
      "definition": "13世纪天主教安魂弥撒的格里高利圣咏旋律，在此象征不可逆转的死亡命运与末世审判。",
      "definition_en": "13th-century Gregorian chant sequence from the Requiem Mass, symbolizing mortality and apocalyptic judgment."
    },
    {
      "term": "Aufschrei / Totengreif (绝望尖叫和弦)",
      "term_en": "The Scream of Despair (Aufschrei)",
      "definition": "第三乐章与第五乐章爆发的降B小调极不协和全奏崩塌和弦，如同面对虚无宇宙时发自灵魂深处的绝望悲鸣。",
      "definition_en": "A catastrophic, dissonant B-flat minor tutti explosion capturing existential dread before the abyss."
    }
  ],
