      "note": "内置音轨采用西蒙·拉特尔爵士率领柏林爱乐乐团在柏林爱乐大厅录制的经典名盘（独唱：凯特·罗亚尔与玛格达莱娜·科泽娜；合唱：柏林广播合唱团）。拉特尔以冷冽如刀锋的弦乐咬弦、深邃的后台乐队距离感与震天撼地的终曲管风琴轰鸣，构建出马勒末世救赎哲学的极致体验。"
